input.new_string:
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMember(invitation.orgId, userId);

  // A current member accepting uses the invitation up and changes nothing
  // about them: not their role, and not the seats they already occupy.
  if (isCurrentMember(existing)) {
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      acceptedAt,
    );
    return existing;
  }

  // A former member comes back on the membership the workspace already knew.
  // Anyone else gets a new row. Either way the invitation is spent once.
  const member = existing
    ? await memberRepo.reactivateMember(
        invitation.orgId,
        existing.id,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

