import { AlreadyArchivedError } from "@/lib/soft-delete";
import { hashToken } from "@/lib/hash";
import { subscribe } from "@/lib/event-bus";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { listDigestRecipients, buildDigest } from "@/server/services/digest-service";
import * as projectService from "@/server/services/project-service";
import { resolveActorForOrg, switchActiveOrg } from "@/server/services/session-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../private/tmp/bench-scratch/9ec62673-8a01-4f85-92e4-5ef1f97a80f1/tests/server/_support/fixtures";
import { toIsoTimestamp } from "@/types/common";
import type { SessionPrincipal } from "@/types/member";

let cleanup: () => void;
let offUsage: (() => void) | undefined;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  offUsage = registerUsageListeners();
});

afterAll(() => {
  offUsage?.();
  cleanup();
});

function principal(userId: SessionPrincipal["userId"], email: string): SessionPrincipal {
  return {
    userId,
    email,
    activeOrgId: null,
    expiresAt: toIsoTimestamp(new Date(Date.now() + 86_400_000)),
  };
}

describe("former members", () => {
  it("covers removal, re-invite, notifications, assignment and conflicts", async () => {
    const tenant = await createTenant("former", "growth");
    const other = await createTenant("other-ws", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    await usageRepo.recomputeUsage(other.org.id);

    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!viewer || !admin) throw new Error("fixture");

    await memberRepo.insertMember(other.org.id, tenant.userIds.viewer, "member", null);
    const otherMembership = await memberRepo.findMember(other.org.id, tenant.userIds.viewer);

    const led = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Led by viewer",
      slug: "led-by-viewer",
      key: "LED",
      description: null,
      visibility: "org",
      leadId: tenant.userIds.viewer,
      color: "#6366f1",
      targetDate: null,
    });
    const assigned = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Assigned to viewer",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const authored = await issueService.createIssue(
      tenant.actors.viewer,
      issueInput(tenant.org.id, tenant.project.id, { title: "Opened by viewer" }),
    );

    const beforeSeats = (await usageRepo.getUsage(tenant.org.id)).seatsUsed;

    const removed = await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });
    expect(removed.id).toBe(viewer.id);
    expect(removed.archivedAt).not.toBeNull();
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(beforeSeats - 1);

    const listed = await memberRepo.listMembers({
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
    });
    expect(listed.items.some((row) => row.userId === tenant.userIds.viewer)).toBe(false);

    expect(await memberService.resolveActor(tenant.userIds.viewer, tenant.org.id)).toBeNull();
    expect(
      await resolveActorForOrg(principal(tenant.userIds.viewer, "viewer@former.test"), tenant.org.slug),
    ).toBeNull();
    await expect(
      switchActiveOrg(principal(tenant.userIds.viewer, "viewer@former.test"), {
        orgId: tenant.org.id,
      }),
    ).rejects.toThrow(/not a member/);
    expect(await orgRepo.listOrgsForUser(tenant.userIds.viewer)).toEqual(
      expect.arrayContaining([expect.objectContaining({ id: other.org.id })]),
    );
    expect(
      (await orgRepo.listOrgsForUser(tenant.userIds.viewer)).some((org) => org.id === tenant.org.id),
    ).toBe(false);

    await expect(
      commentService.createComment(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: authored.id,
        body: "still here",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeTruthy();

    expect((await issueRepo.findIssueById(tenant.org.id, assigned.id))?.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(tenant.org.id, led.id))?.leadId).toBeNull();
    expect((await memberRepo.findMember(other.org.id, tenant.userIds.viewer))?.id).toBe(
      otherMembership?.id,
    );
    expect((await memberRepo.findMember(other.org.id, tenant.userIds.viewer))?.archivedAt).toBeNull();

    const outside = await userRepo.insertUser({
      email: "outsider@former.test",
      name: "Outsider",
      passwordHash: "seed",
    });
    const beforeIssues = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    const beforeProjects = await projectRepo.countProjects(tenant.org.id);
    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Cannot assign former",
          assigneeId: tenant.userIds.viewer,
        }),
      ),
    ).rejects.toThrow(/not a current member/);
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: authored.id,
        assigneeId: outside.id,
      }),
    ).rejects.toThrow(/not a current member/);
    expect((await issueRepo.findIssueById(tenant.org.id, authored.id))?.assigneeId).toBeNull();
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(beforeIssues);

    const kept = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    await expect(
      projectService.createProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        name: "Bad lead",
        slug: "bad-lead",
        key: "BAD",
        description: "nope",
        visibility: "org",
        leadId: tenant.userIds.viewer,
        color: "#6366f1",
        targetDate: null,
      }),
    ).rejects.toThrow(/not a current member/);
    await expect(
      projectService.updateProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "Renamed anyway",
        leadId: outside.id,
      }),
    ).rejects.toThrow(/not a current member/);
    expect(await projectRepo.countProjects(tenant.org.id)).toBe(beforeProjects);
    expect((await projectRepo.findProjectById(tenant.org.id, tenant.project.id))?.name).toBe(
      kept?.name,
    );

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: authored.id,
      body: "hello @viewer and @outsider",
      parentId: null,
      mentionedUserIds: [tenant.userIds.viewer, outside.id],
    });
    expect(comment.mentionedUserIds).not.toContain(tenant.userIds.viewer);
    expect(comment.mentionedUserIds).not.toContain(outside.id);

    const rows = await notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.viewer, tenant.userIds.admin],
      {
        title: "New comment",
        body: "after they left",
        href: "/issues/x",
        actorId: tenant.userIds.member,
      },
    );
    expect(rows.map((row) => row.recipientId)).toEqual([tenant.userIds.admin]);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "comment_created",
      inApp: false,
      email: false,
      digestOnly: true,
    });
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "comment_created",
      inApp: false,
      email: false,
      digestOnly: true,
    });
    const recipients = await listDigestRecipients(tenant.org.id);
    expect(recipients).not.toContain(tenant.userIds.viewer);
    expect(recipients).toContain(tenant.userIds.admin);
    expect(
      await buildDigest(
        tenant.org.id,
        tenant.userIds.viewer,
        toIsoTimestamp(new Date(Date.now() - 86_400_000)),
        toIsoTimestamp(new Date()),
      ),
    ).toBeNull();

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "admin",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await memberRepo.findMemberById(tenant.org.id, viewer.id))?.role).toBe("viewer");

    let roleEvents = 0;
    const off = subscribe("member.role_changed", () => {
      roleEvents += 1;
    });
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    off();
    expect(roleEvents).toBe(0);

    const seatsAfterRemove = (await usageRepo.getUsage(tenant.org.id)).seatsUsed;
    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(seatsAfterRemove);

    const rawToken = "d".repeat(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "viewer@former.test",
        role: "admin",
        expiresInDays: 14,
      },
      tenant.userIds.owner,
      hashToken(rawToken),
    );
    const rejoined = await invitationService.acceptInvitation(tenant.userIds.viewer, {
      token: rawToken,
    });
    expect(rejoined.id).toBe(viewer.id);
    expect(rejoined.archivedAt).toBeNull();
    expect(rejoined.status).toBe("active");
    expect(rejoined.role).toBe("admin");
    expect(rejoined.invitedBy).toBe(tenant.userIds.owner);
    expect(rejoined.joinedAt).not.toBeNull();
    expect(rejoined.lastSeenAt).toBe(viewer.lastSeenAt);
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(seatsAfterRemove + 1);
    const listedAgain = await memberRepo.listMembers({
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
    });
    expect(listedAgain.items.filter((row) => row.userId === tenant.userIds.viewer)).toHaveLength(1);
    expect(await orgRepo.listOrgsForUser(tenant.userIds.viewer)).toEqual(
      expect.arrayContaining([expect.objectContaining({ id: tenant.org.id })]),
    );
    expect(await memberService.resolveActor(tenant.userIds.viewer, tenant.org.id)).toMatchObject({
      role: "admin",
    });

    await expect(
      invitationService.acceptInvitation(tenant.userIds.viewer, { token: rawToken }),
    ).rejects.toThrow(/already been accepted/);

    const second = "e".repeat(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "viewer@former.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(second),
    );
    const seatsNow = (await usageRepo.getUsage(tenant.org.id)).seatsUsed;
    const again = await invitationService.acceptInvitation(tenant.userIds.viewer, {
      token: second,
    });
    expect(again.role).toBe("admin");
    expect(again.joinedAt).toBe(rejoined.joinedAt);
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(seatsNow);
    const storedInvite = await invitationRepo.findInvitationByTokenHash(hashToken(second));
    expect(storedInvite?.acceptedAt).not.toBeNull();

    const stranger = await userRepo.insertUser({
      email: "stranger@former.test",
      name: "Stranger",
      passwordHash: "seed",
    });
    const third = "f".repeat(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "someone-else@former.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.owner,
      hashToken(third),
    );
    const joined = await invitationService.acceptInvitation(stranger.id, { token: third });
    expect(joined.userId).toBe(stranger.id);
    await expect(
      invitationService.acceptInvitation(tenant.userIds.admin, { token: third }),
    ).rejects.toThrow(/already been accepted/);
    expect((await memberRepo.findMember(tenant.org.id, tenant.userIds.admin))?.role).toBe("admin");

    const forViewer = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(forViewer.items.every((row) => row.title !== "New comment" || row.body !== "after they left")).toBe(
      true,
    );

    const after = await notify(
      tenant.org.id,
      "issue_overdue",
      [tenant.userIds.viewer],
      {
        title: "Overdue after return",
        body: "now a member",
        href: "/issues/y",
        actorId: null,
      },
    );
    expect(after).toHaveLength(1);
  });
});

