/**
 * True for a membership that can still act, be notified, be assigned work, or
 * lead a project. Removal archives the row and leaves `status` as history, so
 * neither field on its own is enough.
 */
export function isCurrentMember(
  member: Member | null | undefined,
): member is Member {
  return member != null && member.status === "active" && isLive(member);
130→}

/** Refuses the whole change when `userId` is not a current member of `orgId`. */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!isCurrentMember(member)) {
    throw new Error(`${userId} is not a current member of this workspace`);
140→  }
