 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here. A former member resolves to null even when a
 * session minted before they left is still valid.
 */
export async function resolveActor(
150→  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!isCurrentMember(member)) return null;

  return { userId, orgId, role: member.role };
}

/**
160→ * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner. Exported because both the demote and the remove path need
